from typing import List, Dict

from boto3.dynamodb.conditions import Key

from dynamodb.dynamodb_service import DynamoDBService, DynamoDBQueryRequest
from dynamodb.entity.todo.todo_entity import TodoEntity
from util.logs import Log, LogEventType


class TodoQueryResponse:
    def __init__(self, items: List[Dict], last_evaluated_key: dict):
        self.items = [TodoEntity.from_dict(item) for item in items]
        self.last_evaluated_key = last_evaluated_key


class TodoEntityRepo(DynamoDBService):

    def put_todo(self, todo: TodoEntity):
        try:
            self.put_item(item=todo.to_dict())
        except Exception as e:
            Log(data=str(e), event_type=LogEventType.DynamoDBException).exception()
            raise e

    def find_all_todo_by_list_id(
        self, list_id: str, next_token: str, limit: int = None
    ) -> TodoQueryResponse:
        try:
            exclusive_start_key = (
                {"pk": list_id, "sk": f"{TodoEntity.entity_type.value}#{next_token}"}
                if next_token
                else None
            )
            response = self.query(
                DynamoDBQueryRequest(
                    key_condition_expression=Key("pk").eq(list_id)
                    & Key("sk").begins_with(f"{TodoEntity.entity_type.value}#"),
                    exclusive_start_key=exclusive_start_key,
                    limit=limit,
                )
            )
            return TodoQueryResponse(
                items=response.items, last_evaluated_key=response.last_evaluated_key
            )
        except Exception as e:
            Log(data=str(e), event_type=LogEventType.DynamoDBException).exception()
            raise e

    def update_todo(self, list_id: str, todo_id: str, updates):
        try:
            self.update_item(
                key={"pk": list_id, "sk": f"{TodoEntity.entity_type.value}#{todo_id}"},
                updates=updates,
                item_entity_class_instance=TodoEntity(),
            )
        except Exception as e:
            Log(data=str(e), event_type=LogEventType.DynamoDBException).exception()
            raise e
